// Finds an order reference like #1042 in each email's subject or body and
// builds the Shopify search string. No reference: search by the sender's address.
// Every email in the poll gets its own item, so none is skipped.
const safe = (s) => String(s || '').replace(/["\\]/g, '');
return $input.all().map((item, i) => {
  const m = item.json;
  const hay = (m.subject || '') + '\n' + (m.text || '');
  const hit = hay.match(/#\s?(\d{3,7})\b/) || hay.match(/\border\s*(?:no\.?|number|ref(?:erence)?)?\s*:?\s*#?(\d{3,7})\b/i);
  const orderName = hit ? '#' + hit[1] : '';
  const searchQuery = orderName ? 'name:' + orderName : (m.fromAddress ? 'email:"' + safe(m.fromAddress) + '"' : '');
  return { json: { ...m, orderName, searchQuery, lookupBy: orderName ? 'order number' : 'sender email' }, pairedItem: { item: i } };
});

// Pairs each Shopify answer with its email, picks the matching order, checks
// the email on it against the sender, and writes the record as plain text for
// the model. Nothing here calls a model.
const mails = $('Find the order reference').all();
return $input.all().map((item, i) => {
  const res = item.json || {};
  let mail;
  try { mail = $('Find the order reference').itemMatching(i).json; } catch (e) { mail = mails[i].json; }
  const edges = res && res.data && res.data.orders && Array.isArray(res.data.orders.edges) ? res.data.orders.edges : [];
  const lookupError = res && res.errors ? JSON.stringify(res.errors).slice(0, 300) : (res && res.error ? String(res.error.message || res.error).slice(0, 300) : '');
  let order = null;
  if (mail.orderName) order = (edges.find((e) => e.node && e.node.name === mail.orderName) || {}).node || null;
  else if (edges.length) order = edges[0].node;
  const orderFound = !!order;
  const emailMatches = !!(order && order.email && mail.fromAddress && order.email.toLowerCase() === mail.fromAddress);
  const lines = [];
  if (order) {
    lines.push('Order ' + order.name + ', placed ' + String(order.processedAt || '').slice(0, 10) + (order.cancelledAt ? ', CANCELLED ' + String(order.cancelledAt).slice(0, 10) : ''));
    lines.push('Payment: ' + (order.displayFinancialStatus || 'unknown') + '. Fulfilment: ' + (order.displayFulfillmentStatus || 'unknown') + '.');
    if (order.totalPriceSet && order.totalPriceSet.shopMoney) lines.push('Total: ' + order.totalPriceSet.shopMoney.amount + ' ' + order.totalPriceSet.shopMoney.currencyCode);
    if (order.shippingAddress) lines.push('Ships to: ' + [order.shippingAddress.city, order.shippingAddress.country].filter(Boolean).join(', '));
    const items = ((order.lineItems || {}).edges || []).map((e) => e.node.quantity + ' x ' + e.node.title);
    if (items.length) lines.push('Items: ' + items.join('; '));
    for (const f of order.fulfillments || []) {
      const t = (f.trackingInfo || [])[0] || {};
      lines.push('Shipment: ' + (f.status || 'unknown') + (t.company ? ', carrier ' + t.company : '') + (t.number ? ', tracking ' + t.number : '') + (t.url ? ', ' + t.url : '') + (f.estimatedDeliveryAt ? ', estimated delivery ' + String(f.estimatedDeliveryAt).slice(0, 10) : ''));
    }
    if (!(order.fulfillments || []).length) lines.push('Shipment: not yet dispatched.');
  }
  return { json: { ...mail, orderFound, emailMatches, orderName: order ? order.name : mail.orderName, orderText: lines.join('\n'), lookupError }, pairedItem: { item: i } };
});

