// Reads the model's JSON for each email and decides the route with your rules.
// The model never picks the route. Anything unclear goes to a person, never guessed.
const settings = $('Settings').first().json;
const allowed = String(settings.autoSendIntents || '').split(',').map((s) => s.trim()).filter(Boolean);
const bar = Number(settings.confidenceBar);
const briefs = $('Prepare the brief').all();
return $input.all().map((item, i) => {
  const res = item.json;
  let mail;
  try { mail = $('Prepare the brief').itemMatching(i).json; } catch (e) { mail = briefs[i].json; }
  let out = null; let failure = '';
  if (!res || res.error) failure = 'the model call failed: ' + (res && res.error ? String(res.error.message || res.error).slice(0, 160) : 'no response');
  else if (res.stop_reason === 'refusal') failure = 'the model declined to answer';
  else { const block = Array.isArray(res.content) ? res.content.find((b) => b.type === 'text') : null; try { out = JSON.parse(block.text); } catch (e) { failure = 'the model returned no usable JSON'; } }
  let route = 'escalate', reason = failure;
  if (out) {
    if (out.intent === 'spam_or_newsletter') { route = 'skip'; reason = 'spam or newsletter'; }
    else if (out.intent === 'complaint_or_escalation' || out.intent === 'wholesale_or_partnership') { route = 'escalate'; reason = out.intent.replace(/_/g, ' '); }
    else if (mail.orderFound && !mail.emailMatches) { route = 'escalate'; reason = 'the email on order ' + mail.orderName + ' does not match the sender'; }
    else if (mail.isReply) { route = 'draft'; reason = 'a reply in an existing thread; the workflow only sends the first answer'; }
    else if (!allowed.includes(out.intent)) { route = 'draft'; reason = out.intent.replace(/_/g, ' ') + ' is not on the send list'; }
    else if (out.needs_person) { route = 'draft'; reason = out.reason || 'the model asked for a person'; }
    else if (!(Number(out.confidence) >= bar)) { route = 'draft'; reason = 'confidence ' + out.confidence + ' is below the bar of ' + bar; }
    else if (out.intent === 'order_status' && !mail.orderFound) { route = 'draft'; reason = mail.lookupError ? 'the Shopify lookup failed, so the draft has no order record: ' + mail.lookupError.slice(0, 160) : 'no order found for ' + (mail.searchQuery || 'this sender') + '; the draft asks for the order number'; }
    else { route = 'send'; reason = 'on the send list at confidence ' + out.confidence; }
  }
  const body = out ? String(out.reply || '').trim() : '';
  const draftSubject = /^\s*re\s*:/i.test(mail.subject || '') ? mail.subject : 'Re: ' + (mail.subject || 'your message');
  const replyText = body + '\n\n' + settings.signature + '\n\n' + settings.disclosureLine;
  const draftText = body + '\n\n' + settings.signature;
  return { json: { ...mail, ...(out || {}), route, reason, replyText, draftText, draftSubject, threadLink: 'https://mail.google.com/mail/u/0/#all/' + mail.threadId, decidedAt: new Date().toISOString() }, pairedItem: { item: i } };
});

